const totalReais = 157.9;
const amigos = 4;

// calcule em centavos e mostre as quatro linhas aqui

exercises.solution:
const totalReais = 157.9;
const amigos = 4;

const totalCentavos = Math.round(totalReais * 100);
const porAmigo = Math.floor(totalCentavos / amigos);
const sobra = totalCentavos % amigos;

console.log(`Total: R$ ${(totalCentavos / 100).toFixed(2)}`);
console.log(`Cada amigo paga: R$ ${(porAmigo / 100).toFixed(2)}`);
console.log(`Centavos que sobram: ${sobra}`);
console.log(`Conferindo: ${porAmigo * amigos + sobra} centavos`);

